/* Service Worker – Enyaq Ladekosten
 * - App-Shell (index.html) und die CDN-Skripte werden gecacht, die App startet dadurch auch offline.
 * - HTML: "Network first" (du bekommst nach einem Deploy sofort die neue Version, offline den Cache).
 * - Skripte/Schriften/sonstige Dateien: "Stale while revalidate" (schnell aus dem Cache, im Hintergrund aktualisiert).
 * - Die KI-Abfrage (/api/…) wird NIE gecacht und läuft immer übers Netz.
 * Bei größeren Änderungen am Cache-Konzept CACHE_VERSION erhöhen. */

const CACHE_VERSION = 'v388';
const CACHE_NAME = 'enyaq-' + CACHE_VERSION;

// Dateien, die beim Installieren vorab geladen werden
const SAME_ORIGIN_ASSETS = ['./', './index.html', './app.css?v=388', './app.js?v=388', './Bilder/Enyaq/hero/1.webp'];
const CDN_ASSETS = [
  'https://cdn.jsdelivr.net/npm/chart.js@4.4.3/dist/chart.umd.min.js'
];

self.addEventListener('install', (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE_NAME);
    // einzeln laden: hakt eine Datei, bricht nicht die ganze Installation ab (sonst bleibt der alte Service Worker aktiv)
    await Promise.all(SAME_ORIGIN_ASSETS.map(async (u) => { try { await cache.add(new Request(u, { cache: 'reload' })); } catch (err) { console.warn('[SW] Vorab-Caching fehlgeschlagen:', u, err); } }));
    // CDN-Dateien einzeln und "no-cors" laden (opake Antworten sind cachebar); ein Fehler bricht die Installation nicht ab
    await Promise.all(CDN_ASSETS.map(async (url) => {
      try { await cache.put(url, await fetch(new Request(url, { mode: 'no-cors' }))); }
      catch (err) { console.warn('[SW] Vorab-Caching fehlgeschlagen:', url, err); }
    }));
    await self.skipWaiting();
  })());
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    // alte Cache-Versionen entfernen
    const names = await caches.keys();
    await Promise.all(names.filter((n) => n.startsWith('enyaq-') && n !== CACHE_NAME).map((n) => caches.delete(n)));
    await self.clients.claim();
  })());
});

/** multipart/form-data als Text zerlegen → [{ name, filename, type, data }] (nur für Textdateien gedacht) */
function shareParts(body, ct) {
  const m = /boundary=(?:"([^"]+)"|([^;]+))/i.exec(ct || ''), b = m ? (m[1] || m[2]).trim() : (/^--([^\r\n]+)/.exec(body) || [])[1];
  if (!b) return [];
  return body.split('--' + b).slice(1).filter((p) => !/^--\s*$/.test(p) && p.trim() !== '--').map((p) => {
    p = p.replace(/^\r?\n/, ''); const i = p.search(/\r?\n\r?\n/); if (i < 0) return null;
    const head = p.slice(0, i), data = p.slice(i).replace(/^\r?\n\r?\n/, '').replace(/\r?\n$/, '');
    const g = (re) => (re.exec(head) || [])[1] || '';
    return { name: g(/name="([^"]*)"/i), filename: g(/filename="([^"]*)"/i), type: g(/content-type:\s*([^\r\n;]+)/i).trim(), data };
  }).filter(Boolean);
}
self.addEventListener('fetch', (event) => {
  const req = event.request;
  const url = new URL(req.url);

  /* Teilen-Menü (Android, installierte App): MyŠkoda → Fahrtenbuch → Export → Teilen → diese App. Die Datei kommt als POST an /share-target;
     sie wird kurz im Cache „enyaq-share“ abgelegt, die App öffnet Start und importiert sie dort (src/18-teilen.js). */
  if (req.method === 'POST' && url.origin === self.location.origin && url.pathname === '/share-target') {
    event.respondWith((async () => {
      const cache = await caches.open('enyaq-share'), raw = req.clone(), ct = req.headers.get('content-type') || '';
      const keep = (data, type, name) => cache.put('/share-file', new Response(data, { headers: { 'content-type': type || 'text/csv', 'x-name': encodeURIComponent(name || 'fahrtenbuch.csv') } }));
      try { await cache.delete('/share-file'); } catch (e) { }
      try {
        /* Datei unter jedem Feldnamen annehmen (Chrome: „file“); sonst Text mit CSV-Inhalt */
        const vals = [...(await req.formData()).values()];
        const f = vals.find((v) => v && typeof v !== 'string' && v.size > 0), t = vals.find((v) => typeof v === 'string' && /Start of trip/.test(v));
        if (f) await keep(f, f.type, f.name); else if (t) await keep(t);
      } catch (err) {
        /* Samsung Internet: formData() scheitert („Failed to fetch“), der Rohinhalt ist aber lesbar → multipart selbst zerlegen (CSV ist Text) */
        try { const part = shareParts(await raw.text(), ct).find((x) => x.filename || /Start of trip/.test(x.data)); if (part && part.data) await keep(part.data, part.type, part.filename); }
        catch (e) { console.warn('[SW] Teilen fehlgeschlagen:', err, e); }
      }
      return Response.redirect(new URL('/?go=fb-share', self.location.origin).href, 303);
    })());
    return;
  }
  if (req.method !== 'GET') return;                              // POST (KI-Abfrage) nie anfassen
  if (url.origin === self.location.origin && url.pathname.startsWith('/api/')) return;
  if (!/^https?:$/.test(url.protocol)) return;
  // Fremde Hosts nur für die bekannten Skript-CDNs cachen – Firestore/Auth (Streaming, Login-Iframe/Popup) niemals anfassen
  const CDN_HOSTS = ['cdn.jsdelivr.net', 'www.gstatic.com'];
  if (url.origin !== self.location.origin && !CDN_HOSTS.includes(url.hostname)) return;
  if (url.searchParams.has('vcheck')) return;                                   // Versions-Prüfung der App: immer direkt ans Netz, nichts zwischenspeichern

  // Seitenaufrufe: Network first, offline -> gecachte index.html
  if (req.mode === 'navigate') {
    event.respondWith((async () => {
      try {
        const fresh = await fetch(req);
        const cache = await caches.open(CACHE_NAME);
        cache.put('./index.html', fresh.clone());
        return fresh;
      } catch (err) {
        return (await caches.match('./index.html')) || (await caches.match('./')) || Response.error();
      }
    })());
    return;
  }

  // Alles andere: Stale while revalidate
  event.respondWith((async () => {
    const cache = await caches.open(CACHE_NAME);
    const cached = await cache.match(req);
    const network = fetch(req).then((res) => {
      if (res && (res.ok || res.type === 'opaque')) cache.put(req, res.clone());
      return res;
    }).catch(() => cached);
    return cached || network;
  })());
});

/* ---- Push-Benachrichtigungen (Eis-Warnung am Vorabend, Testnachricht) ---- */
/* Große Push-Bilder (rechts): einheitliches Set „dunkle Kachel + farbiges Symbol“ je Art, 192 px; ice = Standard */
const PUSH_ICON_C = {"ice": "data:image/png;base64,", "rem": "data:image/png;base64,", "low": "data:image/png;base64,", "veh": "data:image/png;base64,", "mon": "data:image/png;base64,", "key": "data:image/png;base64,", "bd": "data:image/png;base64,", "win": "data:image/png;base64,"};
const PUSH_BADGE = 'data:image/png;base64,';
const PUSH_BADGE_REM = 'data:image/png;base64,';  // Erinnerung: Glocke (Statusleiste)
const PUSH_BADGE_LOW = 'data:image/png;base64,';
const PUSH_IMG_MORE = { win: ['', 'data:image/png;base64,'], bd: ['', 'data:image/png;base64,'], veh: ['', 'data:image/png;base64,'], mon: ['', 'data:image/png;base64,'], key: ['', 'data:image/png;base64,'] };   // Auto offen, Monatsanfang, Schlüssel
self.addEventListener('push', (event) => {
  let d = {}; try { d = event.data ? event.data.json() : {}; } catch (e) { d = { title: 'EnyaqStrom', body: event.data ? event.data.text() : '' }; }
  event.waitUntil(self.registration.showNotification(d.title || 'EnyaqStrom', {
    body: d.body || '', tag: d.tag || 'enyaq', renotify: true, badge: d.kind === 'rem' ? PUSH_BADGE_REM : d.kind === 'low' ? PUSH_BADGE_LOW : PUSH_IMG_MORE[d.kind] ? PUSH_IMG_MORE[d.kind][1] : PUSH_BADGE, icon: PUSH_ICON_C[d.kind] || PUSH_ICON_C.ice,   // Bilder eingebettet: beim Aufwecken aus dem Ruhezustand ist oft kein Netz da, sonst zeigt Android „E“ und eine Glocke
    data: { url: d.url || '/' }, actions: [{ action: 'open', title: 'Details' }, { action: 'close', title: 'OK' }]
  }));
});
self.addEventListener('notificationclick', (event) => {
  event.notification.close(); if (event.action === 'close') return;
  const url = (event.notification.data && event.notification.data.url) || '/';
  event.waitUntil((async () => {
    const all = await self.clients.matchAll({ type: 'window', includeUncontrolled: true });
    for (const c of all) { if (new URL(c.url).origin === self.location.origin) { await c.focus(); if (url !== '/' && c.navigate) await c.navigate(url).catch(() => { }); return; } }   // z. B. Erinnerung → /?go=reminders
    await self.clients.openWindow(url);
  })());
});
